<?php require __DIR__.'/../bootstrap.php';require_admin();$tid=(int)getv('thread',0);$threads=db()->query('SELECT st.*,u.full_name,u.email FROM support_threads st JOIN users u ON u.id=st.user_id ORDER BY st.updated_at DESC')->fetchAll();$messages=[];if($tid){$s=db()->prepare('SELECT * FROM support_messages WHERE thread_id=? ORDER BY id');$s->execute([$tid]);$messages=$s->fetchAll();}$title='Support Chat';require __DIR__.'/../includes/header.php';?>
<div class="page-head"><div><span class="eyebrow">Administration</span><h1>Customer Support Chat</h1><p>Direct 1-on-1 customer conversations. User messages are on the left; admin replies are on the right.</p></div></div>
<div class="support-shell support-chat-live support-chat-admin"><aside class="card"><h3>Customers</h3><div id="thread-list"><?php foreach($threads as $t):?><a class="chat-session <?=$t['id']===$tid?'active':''?>" href="/admin/support/?thread=<?=$t['id']?>"><strong><?=e($t['full_name'])?></strong><small class="muted"> · <?=e($t['status'])?></small><br><span class="muted"><?=e($t['email'])?></span></a><?php endforeach;?></div></aside><section class="card"><div class="support-messages" id="support-messages" data-thread="<?=$tid?>"><?php foreach($messages as $m):?><div class="support-message <?=$m['sender_role']==='admin'?'from-admin':'from-user'?>" data-mid="<?=$m['id']?>"><small><?=e($m['sender_role']==='admin'?'Admin':'Customer')?> · <?=e($m['created_at'])?></small><div><?=nl2br(e($m['body']))?></div><?php $atts=json_decode((string)($m['attachment_paths']??''),true);if(!is_array($atts)||!$atts)$atts=!empty($m['attachment_path'])?[$m['attachment_path']]:[];foreach($atts as $att):?><p><a class="btn small secondary" target="_blank" href="<?=e($att)?>">Open attachment</a></p><?php endforeach;?></div><?php endforeach;?></div><?php if($tid):?><form id="support-form" class="support-composer" method="post" enctype="multipart/form-data"><?=csrf_field()?><input type="hidden" name="thread_id" value="<?=$tid?>"><textarea name="body" id="support-input" rows="3" placeholder="Reply to customer…"></textarea><div class="support-upload-picker"><strong>Upload files</strong><button type="button" class="btn small secondary" id="support-choose-files">Choose files</button><span class="muted">Bulk upload · resumable · retry/cancel</span><input type="file" id="support-file" name="files[]" multiple hidden accept="image/*,audio/*,video/*,.zip,.pdf,.txt,.csv,.json,.doc,.docx,.xls,.xlsx,.ppt,.pptx"></div><div id="support-attachments" class="upload-list"></div><div class="composer-row"><span class="muted">Your replies appear on the right.</span><button class="btn">Send Reply</button></div></form><?php endif;?></section></div>
